vulnerable_example.code:
@router.post("/users")
async def creer(payload: dict):
    return await User.create(**payload)     # is_admin passe si le client l'envoie

fixed_example.code:
class UserCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")   # champ inconnu = 422
    email: EmailStr
    nom: str
    # is_admin n'est pas exposé : il n'est pas ecrivable par le client.

@router.post("/users")
async def creer(payload: UserCreate):
    return await User.create(email=payload.email, nom=payload.nom)
